def _validate_value(x):
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise TypeError("values must contain only ints or floats")
    if isinstance(x, float) and isnan(x):
        raise ValueError("values must not contain NaN")


def _validate_values(values):
    for x in values:
        _validate_value(x)


def longest_calm(values, limit):
    _validate_limit(limit)
    _validate_values(values)

    n = len(values)
    if n == 0:
        return (0, 0)

    max_deque = deque()
    min_deque = deque()
    best_i = 0
    best_j = 1
    left = 0

    for right in range(n):
        x = values[right]
        while max_deque and values[max_deque[-1]] <= x:
            max_deque.pop()
        max_deque.append(right)
        while min_deque and values[min_deque[-1]] >= x:
            min_deque.pop()
        min_deque.append(right)

        while (
            max_deque
            and min_deque
            and values[max_deque[0]] - values[min_deque[0]] > limit
        ):
            if max_deque[0] == left:
                max_deque.popleft()
            if min_deque[0] == left:
                min_deque.popleft()
            left += 1

        window_len = right - left + 1
        if window_len > best_j - best_i:
            best_i = left
            best_j = right + 1

    return (best_i, best_j)


def count_calm(values, limit):
