class CycleError(ValueError):
    def __init__(self, nodes):
        self.nodes = nodes
        super().__init__(f"cycle detected involving nodes: {nodes}")


def _build_graph(nodes, edges):
    node_set = set(nodes)
    for before, after in edges:
        if before not in node_set:
            raise ValueError(f"unknown node: {before}")
        if after not in node_set:
            raise ValueError(f"unknown node: {after}")

    successors = {node: [] for node in node_set}
    predecessors = {node: [] for node in node_set}
    seen_edges = set()
    for before, after in edges:
        if before == after:
            seen_edges.add((before, after))
            predecessors[after].append(before)
            successors[before].append(after)
            continue
        edge = (before, after)
        if edge in seen_edges:
            continue
        seen_edges.add(edge)
        predecessors[after].append(before)
        successors[before].append(after)

    return node_set, successors, predecessors


def topo_order(nodes, edges):
    node_set, successors, predecessors = _build_graph(nodes, edges)

    in_degree = {node: len(preds) for node, preds in predecessors.items()}
    available = sorted(node for node, deg in in_degree.items() if deg == 0)
    result = []

    while available:
        node = available.pop(0)
        result.append(node)
        for succ in successors[node]:
            in_degree[succ] -= 1
            if in_degree[succ] == 0:
                available.append(succ)
                available.sort()

    if len(result) != len(node_set):
        placed = set(result)
        unplaced = node_set - placed
        raise CycleError(sorted(unplaced))

    return result


def layers(nodes, edges):
    node_set, successors, predecessors = _build_graph(nodes, edges)

    remaining_preds = {node: set(preds) for node, preds in predecessors.items()}
    placed = set()
    result = []

    while True:
        current_layer = sorted(
            node for node in node_set
            if node not in placed and not (remaining_preds[node] - placed)
        )
        if not current_layer:
            break
        result.append(current_layer)
        placed.update(current_layer)

    if placed != node_set:
        unplaced = node_set - placed
        raise CycleError(sorted(unplaced))

    return result
