def to_roman(n):
    if type(n) is not int:
        raise TypeError("n must be an int")
    if n < 1 or n > 3999:
        raise ValueError("n must be between 1 and 3999 inclusive")
    values = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
    numerals = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]
    result = []
    for value, numeral in zip(values, numerals):
        while n >= value:
            result.append(numeral)
            n -= value
    return "".join(result)


def from_roman(s):
    if type(s) is not str:
        raise TypeError("s must be a str")
    if not s:
        raise ValueError("empty string is not a valid Roman numeral")
    total = 0
    prev_value = 0
    repeat_count = 1
    subtractive_used = False
    value_map = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    subtractive_pairs = {"IV", "IX", "XL", "XC", "CD", "CM"}
    for i, ch in enumerate(s):
        if ch not in value_map:
            raise ValueError("invalid character in Roman numeral")
        value = value_map[ch]
        if i > 0:
            prev_ch = s[i - 1]
            prev_val = value_map[prev_ch]
            if value == prev_val:
                repeat_count += 1
                if ch in ("V", "L", "D"):
                    raise ValueError("V, L, D cannot be repeated")
                if repeat_count > 3:
                    raise ValueError("symbol repeated more than three times")
                if subtractive_used:
                    raise ValueError("cannot repeat after a subtractive pair")
            elif value > prev_val:
                pair = prev_ch + ch
                if pair not in subtractive_pairs:
                    raise ValueError("invalid subtractive form")
                if i > 1 and value_map[s[i - 2]] <= value:
                    raise ValueError("invalid placement of subtractive pair")
                if repeat_count != 1:
                    raise ValueError("subtractive pair must follow a single symbol")
                total += value - 2 * prev_val
                repeat_count = 1
                subtractive_used = True
            else:
                repeat_count = 1
                subtractive_used = False
                total += value
        else:
            total += value
    if total < 1 or total > 3999:
        raise ValueError("value out of range")
    if to_roman(total) != s:
        raise ValueError("not a canonical Roman numeral")
    return total


def is_roman(s):
    try:
        from_roman(s)
        return True
    except (TypeError, ValueError):
        return False
