def merge(intervals):
    """
    Return a sorted list of disjoint half-open intervals covering the same points.
    Overlapping and touching intervals are merged. Empty intervals are dropped.
    An interval with start > end raises ValueError.
    """
    result = []
    for iv in intervals:
        if len(iv) != 2:
            raise ValueError("Each interval must be a 2-item sequence")
        start, end = iv
        if start > end:
            raise ValueError("Interval start must not be greater than end")
        if start == end:
            continue
        result.append((start, end))
    if not result:
        return []
    result.sort(key=lambda x: x[0])
    merged = [result[0]]
    for start, end in result[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            if end > last_end:
                merged[-1] = (last_start, end)
        else:
            merged.append((start, end))
    return merged


def subtract(a, b):
    """
    Return the points of interval list a that are not in interval list b,
    as a merged, sorted list of half-open intervals.
    """
    a = merge(a)
    b = merge(b)
    if not a:
        return []
    if not b:
        return a
    result = []
    a_idx = 0
    b_idx = 0
    cur_start, cur_end = a[a_idx]
    b_start, b_end = b[b_idx]
    while True:
        if b_end <= cur_start:
            b_idx += 1
            if b_idx >= len(b):
                break
            b_start, b_end = b[b_idx]
        elif b_start >= cur_end:
            result.append((cur_start, cur_end))
            a_idx += 1
            if a_idx >= len(a):
                return result
            cur_start, cur_end = a[a_idx]
        else:
            if b_start > cur_start:
                result.append((cur_start, b_start))
            if b_end >= cur_end:
                a_idx += 1
                if a_idx >= len(a):
                    return result
                cur_start, cur_end = a[a_idx]
            else:
                cur_start = b_end
                b_idx += 1
                if b_idx >= len(b):
                    break
    if a_idx < len(a):
        result.append((cur_start, cur_end))
        a_idx += 1
        result.extend(a[a_idx:])
    return result


def total_length(intervals):
    """
    Return the total length covered by the union of the intervals.
    """
    merged = merge(intervals)
    return sum(end - start for start, end in merged)
