from fractions import Fraction

def evaluate(expr):
    if not isinstance(expr, str):
        raise ValueError("Input must be a string")

    tokens = _tokenize(expr)
    pos = 0

    def peek():
        nonlocal pos
        if pos < len(tokens):
            return tokens[pos]
        return None

    def consume(expected=None):
        nonlocal pos
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of input")
        if expected is not None and tok != expected:
            raise ValueError(f"Expected {expected!r}, got {tok!r}")
        pos += 1
        return tok

    def parse_expr():
        node = parse_term()
        while True:
            tok = peek()
            if tok == '+' or tok == '-':
                op = consume()
                right = parse_term()
                if op == '+':
                    node = node + right
                else:
                    node = node - right
            else:
                break
        return node

    def parse_term():
        node = parse_unary()
        while True:
            tok = peek()
            if tok == '*' or tok == '/':
                op = consume()
                right = parse_unary()
                if op == '*':
                    node = node * right
                else:
                    node = node / right
            else:
                break
        return node

    def parse_unary():
        tok = peek()
        if tok == '-':
            consume()
            val = parse_unary()
            return -val
        return parse_power()

    def parse_power():
        base = parse_atom()
        tok = peek()
        if tok == '^':
            consume()
            exp = parse_unary()
            return _power(base, exp)
        return base

    def parse_atom():
        tok = peek()
        if tok is None:
            raise ValueError("Expected atom, got end of input")
        if isinstance(tok, int):
            consume()
            return Fraction(tok)
        if tok == '(':
            consume()
            val = parse_expr()
            if peek() != ')':
                raise ValueError("Missing closing parenthesis")
            consume(')')
            return val
        raise ValueError(f"Unexpected token: {tok!r}")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Leftover tokens after parsing")

    if result.denominator == 1:
        return result.numerator
    return result


def _tokenize(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c in ' \t':
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(int(expr[i:j]))
            i = j
            continue
        if c in '+-*/^()':
            tokens.append(c)
            i += 1
            continue
        raise ValueError(f"Invalid character: {c!r}")
    return tokens


def _power(base, exp):
    if not isinstance(exp, Fraction):
        raise ValueError("Exponent must be a fraction")
    if exp.denominator != 1:
        raise ValueError("Exponent must be a whole number")
    e = exp.numerator
    if base == 0:
        if e < 0:
            raise ZeroDivisionError("0 cannot be raised to a negative power")
        if e == 0:
            return Fraction(1)
        return Fraction(0)
    if e < 0:
        base = Fraction(1) / base
        e = -e
    result = Fraction(1)
    while e:
        if e & 1:
            result *= base
        base *= base
        e >>= 1
    return result
