def spans(prices):
    if not isinstance(prices, list):
        raise TypeError("prices must be a list")
    n = len(prices)
    result = [0] * n
    stack = []
    for i in range(n):
        p = prices[i]
        if p is None:
            stack.clear()
            result[i] = 0
            continue
        if isinstance(p, bool) or not isinstance(p, (int, float)):
            raise TypeError("price must be int, float, or None")
        while stack:
            j = stack[-1]
            q = prices[j]
            if q is None or q > p:
                break
            stack.pop()
        if not stack:
            result[i] = i + 1
        else:
            result[i] = i - stack[-1]
        stack.append(i)
    return result


def next_greater(prices):
    if not isinstance(prices, list):
        raise TypeError("prices must be a list")
    n = len(prices)
    result = [-1] * n
    stack = []
    for i in range(n - 1, -1, -1):
        p = prices[i]
        if p is None:
            stack.clear()
            result[i] = -1
            continue
        if isinstance(p, bool) or not isinstance(p, (int, float)):
            raise TypeError("price must be int, float, or None")
        while stack:
            j = stack[-1]
            q = prices[j]
            if q is None or q > p:
                break
            stack.pop()
        if stack:
            result[i] = stack[-1]
        else:
            result[i] = -1
        stack.append(i)
    return result


def widest_span(prices):
    span_list = spans(prices)
    best_idx = -1
    best_span = 0
    for i, s in enumerate(span_list):
        if s >= best_span:
            best_span = s
            best_idx = i
    if best_span == 0:
        return (-1, 0)
    return (best_idx, best_span)
