def expand_field(field, lo, hi):
    if not field or not field.strip():
        raise ValueError("invalid cron: empty field")
    values = set()
    for item in field.split(","):
        item = item.strip()
        if not item:
            raise ValueError("invalid cron: empty item")
        step = 1
        if "/" in item:
            base, step_str = item.split("/", 1)
            if not step_str or not step_str.isdigit():
                raise ValueError("invalid cron: malformed step")
            step = int(step_str)
            if step == 0:
                raise ValueError("invalid cron: step cannot be zero")
            item = base
        else:
            base = item
        if item == "*":
            start, end = lo, hi
        elif "-" in item:
            parts = item.split("-", 1)
            if not parts[0].isdigit() or not parts[1].isdigit():
                raise ValueError("invalid cron: malformed range")
            start = int(parts[0])
            end = int(parts[1])
            if start > end:
                raise ValueError("invalid cron: range start greater than end")
        else:
            if not item.isdigit():
                raise ValueError("invalid cron: malformed number")
            start = int(item)
            end = hi
        if start < lo or end > hi:
            raise ValueError("invalid cron: value out of range")
        for v in range(start, end + 1, step):
            values.add(v)
    return sorted(values)


def _parse_expr(expr):
    if not expr or not expr.strip():
        raise ValueError("invalid cron: empty expression")
    fields = expr.strip().split()
    if len(fields) != 2:
        raise ValueError("invalid cron: expression must have exactly two fields")
    minute_field, hour_field = fields
    minutes = expand_field(minute_field, 0, 59)
    hours = expand_field(hour_field, 0, 23)
    return minutes, hours


def cron_matches(expr, hour, minute):
    minutes, hours = _parse_expr(expr)
    return minute in minutes and hour in hours


def next_match(expr, hour, minute):
    minutes, hours = _parse_expr(expr)
    # Search starting from the minute after the given time for the next 24*60 minutes.
    for offset in range(1, 24 * 60 + 1):
        total = (hour * 60 + minute + offset) % (24 * 60)
        h, m = divmod(total, 60)
        if h in hours and m in minutes:
            return (h, m)
    # Should always find a match within one full day.
    raise ValueError("invalid cron: no possible match")
