import bisect


def _validate_intervals(intervals):
    if not isinstance(intervals, list):
        raise TypeError("intervals must be a list")
    for item in intervals:
        if not isinstance(item, tuple) or len(item) != 3:
            raise TypeError("each interval must be a (start, end, weight) tuple")
        start, end, weight = item
        if isinstance(start, bool) or not isinstance(start, int):
            raise TypeError("start must be int")
        if isinstance(end, bool) or not isinstance(end, int):
            raise TypeError("end must be int")
        if isinstance(weight, bool) or not isinstance(weight, int):
            raise TypeError("weight must be int")
        if start >= end:
            raise ValueError("start must be less than end")


def best_schedule(intervals):
    _validate_intervals(intervals)

    n = len(intervals)
    if n == 0:
        return (0, 0)

    # Sort by end, then by start, then by weight descending for tie-breaking
    sorted_intervals = sorted(intervals, key=lambda x: (x[1], x[0], -x[2]))
    ends = [iv[1] for iv in sorted_intervals]

    # dp[i] = (max total weight using intervals among first i+1, min count achieving it)
    # We maintain best total weight and min count for that weight.
    # For each interval, find latest non-overlapping interval j (ends <= start).
    # dp[i] = max(dp[i-1], dp[j] + weight_i)
    # If equal weight, choose fewer intervals.

    # dp_total[i], dp_count[i]
    dp_total = [0] * n
    dp_count = [0] * n

    for i, (start, end, weight) in enumerate(sorted_intervals):
        # find j: largest index with ends[j] <= start
        j = bisect.bisect_right(ends, start) - 1

        if i == 0:
            if weight > 0:
                dp_total[i] = weight
                dp_count[i] = 1
            else:
                dp_total[i] = 0
                dp_count[i] = 0
            continue

        # option 1: not take interval i
        best_total = dp_total[i - 1]
        best_count = dp_count[i - 1]

        # option 2: take interval i
        if j >= 0:
            take_total = dp_total[j] + weight
            take_count = dp_count[j] + 1
        else:
            take_total = weight
            take_count = 1

        if take_total > best_total:
            best_total = take_total
            best_count = take_count
        elif take_total == best_total and take_total > 0:
            # fewer intervals preferred
            if take_count < best_count:
                best_count = take_count

        # If best_total is 0 or negative, represent as (0, 0)
        if best_total <= 0:
            dp_total[i] = 0
            dp_count[i] = 0
        else:
            dp_total[i] = best_total
            dp_count[i] = best_count

    final_total = dp_total[n - 1]
    final_count = dp_count[n - 1]
    if final_total <= 0:
        return (0, 0)
    return (final_total, final_count)


def max_parallel(intervals):
    _validate_intervals(intervals)

    events = []
    for start, end, _ in intervals:
        events.append((start, 1))
        events.append((end, -1))

    # Sort by time; for same time, ends (-1) come before starts (+1) so that
    # touching intervals [a,b) and [b,c) are not counted as overlapping.
    events.sort(key=lambda x: (x[0], x[1]))

    current = 0
    max_count = 0
    for _, delta in events:
        current += delta
        if current > max_count:
            max_count = current

    return max_count
