import heapq
from typing import Any


class MedianTracker:
    def __init__(self, prefer_high: bool = False) -> None:
        self._prefer_high = bool(prefer_high)
        # max-heap for the lower half (stores negatives)
        self._low: list[int] = []
        # min-heap for the upper half
        self._high: list[int] = []
        # delayed deletions
        self._delayed: dict[int, int] = {}
        # effective sizes after accounting for delayed deletions
        self._low_size = 0
        self._high_size = 0

    def _validate_int(self, x: Any) -> int:
        if isinstance(x, bool) or not isinstance(x, int):
            raise TypeError("value must be an int")
        return x

    def add(self, x: Any) -> None:
        x = self._validate_int(x)

        if not self._low or x <= -self._low[0]:
            heapq.heappush(self._low, -x)
            self._low_size += 1
        else:
            heapq.heappush(self._high, x)
            self._high_size += 1

        self._rebalance()

    def remove(self, x: Any) -> None:
        x = self._validate_int(x)

        if x not in self:
            raise ValueError("not present")

        self._delayed[x] = self._delayed.get(x, 0) + 1

        if x <= -self._low[0]:
            self._low_size -= 1
            if x == -self._low[0]:
                self._prune(self._low)
        else:
            self._high_size -= 1
            if self._high and x == self._high[0]:
                self._prune(self._high)

        self._rebalance()

    def median(self) -> int:
        if self._low_size + self._high_size == 0:
            raise LookupError("median is undefined for empty MedianTracker")

        if self._low_size > self._high_size:
            return -self._low[0]

        if self._high_size > self._low_size:
            return self._high[0]

        # even count
        if self._prefer_high:
            return self._high[0]
        else:
            return -self._low[0]

    def __len__(self) -> int:
        return self._low_size + self._high_size

    def __contains__(self, x: Any) -> bool:
        try:
            x = self._validate_int(x)
        except TypeError:
            return False

        # prune tops first to keep delayed counts accurate
        self._prune(self._low)
        self._prune(self._high)

        count = self._delayed.get(x, 0)
        low_count = sum(1 for v in self._low if -v == x)
        high_count = sum(1 for v in self._high if v == x)
        return low_count + high_count > count

    def _prune(self, heap: list[int]) -> None:
        while heap:
            top = -heap[0] if heap is self._low else heap[0]
            if self._delayed.get(top, 0) > 0:
                heapq.heappop(heap)
                self._delayed[top] -= 1
                if self._delayed[top] == 0:
                    del self._delayed[top]
            else:
                break

    def _rebalance(self) -> None:
        # low may have at most one more element than high
        if self._low_size > self._high_size + 1:
            moved = -heapq.heappop(self._low)
            self._low_size -= 1
            heapq.heappush(self._high, moved)
            self._high_size += 1
            self._prune(self._low)
        elif self._low_size < self._high_size:
            moved = heapq.heappop(self._high)
            self._high_size -= 1
            heapq.heappush(self._low, -moved)
            self._low_size += 1
            self._prune(self._high)
