def render(template, values):
    import re

    KEY_RE = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
    SPACE = ' '

    n = len(template)
    out = []
    i = 0

    def is_space(c):
        return c == SPACE

    def strip_spaces(s):
        start = 0
        while start < len(s) and is_space(s[start]):
            start += 1
        end = len(s)
        while end > start and is_space(s[end - 1]):
            end -= 1
        return s[start:end]

    def validate_key(key):
        stripped = strip_spaces(key)
        if not stripped:
            raise ValueError("bad key: " + stripped)
        parts = stripped.split('.')
        for part in parts:
            if not KEY_RE.match(part):
                raise ValueError("bad key: " + stripped)
        return stripped

    def lookup(key):
        parts = key.split('.')
        cur = values
        for part in parts:
            if not isinstance(cur, dict) or part not in cur:
                return None
            cur = cur[part]
        return cur

    def format_value(v):
        if v is True:
            return "true"
        if v is False:
            return "false"
        return str(v)

    while i < n:
        c = template[i]
        if c == '\\':
            if i + 1 < n:
                nxt = template[i + 1]
                if nxt == '\\':
                    out.append('\\')
                    i += 2
                    continue
                if nxt == '{':
                    out.append('{')
                    i += 2
                    continue
                # any other char: backslash literal, then process next char normally
                out.append('\\')
                i += 1
                continue
            else:
                out.append('\\')
                i += 1
                continue
        if c == '{':
            if i + 1 < n and template[i + 1] == '{':
                # placeholder start at i
                start = i
                i += 2
                # find first '}}'
                end = template.find('}}', i)
                if end == -1:
                    raise ValueError("unclosed placeholder at " + str(start))
                content = template[i:end]
                # split at first '|'
                pipe = content.find('|')
                if pipe == -1:
                    key_part = content
                    default_part = None
                else:
                    key_part = content[:pipe]
                    default_part = content[pipe + 1:]
                key = validate_key(key_part)
                val = lookup(key)
                if val is None:
                    if default_part is not None:
                        out.append(strip_spaces(default_part))
                    else:
                        raise KeyError("missing: " + key)
                else:
                    out.append(format_value(val))
                i = end + 2
                continue
            else:
                # single '{'
                out.append('{')
                i += 1
                continue
        # any other char including '}'
        out.append(c)
        i += 1

    return ''.join(out)
