import re


def glob_to_regex(pattern: str) -> str:
    i = 0
    n = len(pattern)
    out = ["^"]
    while i < n:
        ch = pattern[i]
        if ch == "\\":
            if i + 1 < n:
                out.append(re.escape(pattern[i + 1]))
                i += 2
            else:
                out.append(re.escape("\\"))
                i += 1
        elif ch == "?":
            out.append("[^/]")
            i += 1
        elif ch == "*":
            # Determine whether this is a globstar '**' segment.
            if (
                i + 1 < n
                and pattern[i + 1] == "*"
                and (i == 0 or pattern[i - 1] == "/")
                and (i + 2 == n or pattern[i + 2] == "/")
            ):
                # '**' is a whole segment globstar.
                if i + 2 < n and pattern[i + 2] == "/":
                    # '**/' matches zero or more whole path segments, each ending in '/'.
                    out.append("(?:.*/)?")
                    i += 3
                else:
                    # '**' at end matches any remaining text, including '/' and empty string.
                    out.append(".*")
                    i += 2
            else:
                # Any other run of asterisks behaves like a single '*'.
                out.append("[^/]*")
                i += 1
                while i < n and pattern[i] == "*":
                    i += 1
        elif ch == "[":
            j = i + 1
            if j < n and pattern[j] == "!":
                negate = True
                j += 1
            else:
                negate = False
            if j < n and pattern[j] == "]":
                # A ']' right after '[' or '[!' is a literal member.
                class_body = "]"
                j += 1
            else:
                class_body = ""
            start = j
            while j < n and pattern[j] != "]":
                j += 1
            if j >= n:
                # No closing ']' found: '[' is literal.
                out.append(re.escape("["))
                if negate:
                    # We consumed a '!' that turned out not to start a class.
                    out.append(re.escape("!"))
                    i += 2
                else:
                    i += 1
                continue
            class_body += pattern[start:j]
            # Build the character class. A class never matches '/'.
            if negate:
                out.append("[^/")
                if class_body:
                    out.append(class_body)
                out.append("]")
            else:
                out.append("[")
                out.append(class_body)
                out.append("/]")
            i = j + 1
        else:
            out.append(re.escape(ch))
            i += 1
    out.append("$")
    return "".join(out)


def glob_match(pattern: str, path: str) -> bool:
    return re.fullmatch(glob_to_regex(pattern), path) is not None
