import re

_VERSION_RE = re.compile(
    r"^[vV]?(?P<major>0|[1-9]\d*)\.(?P<minor>0|[1-9]\d*)\.(?P<patch>0|[1-9]\d*)"
    r"(?:-(?P<prerelease>[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?"
    r"(?:\+(?P<build>[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?$"
)

_IDENTIFIER_RE = re.compile(r"^[A-Za-z0-9-]+$")


def _parse_identifiers(segment):
    if segment is None:
        return ()
    parts = segment.split(".")
    result = []
    for part in parts:
        if not part:
            raise ValueError("invalid version: empty identifier")
        if not _IDENTIFIER_RE.match(part):
            raise ValueError("invalid version: bad identifier")
        if part.isdigit():
            if part[0] == "0" and part != "0":
                raise ValueError("invalid version: leading zero in numeric identifier")
            result.append(int(part))
        else:
            result.append(part)
    return tuple(result)


def parse_version(text):
    if not isinstance(text, str):
        raise ValueError("invalid version: not a string")
    m = _VERSION_RE.match(text)
    if not m:
        raise ValueError("invalid version: malformed version string")
    major = int(m.group("major"))
    minor = int(m.group("minor"))
    patch = int(m.group("patch"))
    prerelease = _parse_identifiers(m.group("prerelease"))
    build = m.group("build")
    return (major, minor, patch, prerelease, build)


def _compare_prerelease(a, b):
    if not a and not b:
        return 0
    if not a:
        return 1
    if not b:
        return -1
    for x, y in zip(a, b):
        if isinstance(x, int) and isinstance(y, int):
            if x != y:
                return -1 if x < y else 1
        elif isinstance(x, str) and isinstance(y, str):
            if x != y:
                return -1 if x < y else 1
        elif isinstance(x, int):
            return -1
        else:
            return 1
    if len(a) != len(b):
        return -1 if len(a) < len(b) else 1
    return 0


def compare_versions(a, b):
    av = parse_version(a)
    bv = parse_version(b)
    for i in range(3):
        if av[i] != bv[i]:
            return -1 if av[i] < bv[i] else 1
    cmp = _compare_prerelease(av[3], bv[3])
    return cmp


def sort_versions(versions):
    return sorted(versions, key=lambda v: (parse_version(v), object()), cmp=lambda a, b: compare_versions(a, b))
