def parse_ini(text):
    lines = text.split('\n')
    result = {}
    current_section = ''
    current_key = None
    current_value = None
    in_continuation = False

    for i, raw_line in enumerate(lines, start=1):
        line = raw_line
        if line.endswith('\r'):
            line = line[:-1]

        stripped = line.strip()
        if stripped == '':
            # Rule 1: blank/whitespace-only line skipped, ends continuation
            current_key = None
            current_value = None
            in_continuation = False
            continue

        first_non_ws = line.lstrip()[0]
        if first_non_ws in ';#':
            # Rule 2: comment, skipped, does NOT end continuation
            continue

        if line[0] in ' \t':
            # Rule 3: continuation line
            if current_key is None:
                raise ValueError(f'line {i}: continuation without key')
            text_to_append = stripped
            if current_value == '':
                current_value = text_to_append
            else:
                current_value = current_value + ' ' + text_to_append
            result[current_section][current_key] = current_value
            continue

        # Not blank, not comment, not continuation
        # Ends any previous continuation
        current_key = None
        current_value = None
        in_continuation = False

        if stripped.startswith('[') and stripped.endswith(']'):
            # Rule 4: section header
            section_name = stripped[1:-1].strip().lower()
            current_section = section_name
            if current_section not in result:
                result[current_section] = {}
            continue

        # Rule 5: key-value line
        if '=' not in stripped:
            raise ValueError(f'line {i}: missing =')

        key_part, value_part = stripped.split('=', 1)
        key = key_part.strip().lower()
        value = value_part.strip()

        if key == '':
            raise ValueError(f'line {i}: empty key')

        if current_section not in result:
            result[current_section] = {}

        if key in result[current_section]:
            raise ValueError(f'duplicate key {key!r} in section {current_section!r}')

        result[current_section][key] = value
        current_key = key
        current_value = value

    # Rule 6: strip one pair of quotes from values of at least two chars
    for section in result:
        for key in result[section]:
            value = result[section][key]
            if len(value) >= 2 and value.startswith('"') and value.endswith('"'):
                result[section][key] = value[1:-1]

    return result
