import re


def _parse_version(version):
    if version is None:
        raise ValueError("version is None")
    s = str(version).strip()
    if not s:
        raise ValueError("empty version")
    parts = s.split(".")
    if any(part == "" for part in parts):
        raise ValueError("empty version component")
    nums = []
    for part in parts:
        if not re.fullmatch(r"\d+", part):
            raise ValueError("non-numeric version component")
        # strip leading zeros to avoid octal/length issues; 0 is fine
        nums.append(int(part))
    return nums


def _normalize(version_tuple):
    return tuple(version_tuple)


def _compare(a, b):
    # pad with zeros and compare component-wise
    n = max(len(a), len(b))
    for i in range(n):
        av = a[i] if i < len(a) else 0
        bv = b[i] if i < len(b) else 0
        if av < bv:
            return -1
        if av > bv:
            return 1
    return 0


def _parse_spec(spec):
    if spec is None:
        raise ValueError("spec is None")
    s = str(spec).strip()
    if not s:
        return []
    raw_clauses = s.split(",")
    clauses = []
    for raw in raw_clauses:
        clause = raw.strip()
        if not clause:
            raise ValueError("empty spec clause")
        # operator followed by version; allow whitespace between op and version
        m = re.fullmatch(r"(==|!=|>=|<=|>|<|~=)\s*(\S.*)", clause)
        if not m:
            raise ValueError("invalid spec clause")
        op = m.group(1)
        ver_str = m.group(2).strip()
        ver = _parse_version(ver_str)
        if op == "~=" and len(ver) < 2:
            raise ValueError("~= requires at least two version components")
        clauses.append((op, ver))
    return clauses


def _upper_bound_for_compatible(ver):
    # drop last component, increment new last
    upper = list(ver[:-1])
    upper[-1] += 1
    return upper


def satisfies(version, spec):
    ver = _parse_version(version)
    for op, sver in _parse_spec(spec):
        cmp = _compare(ver, sver)
        if op == "==" and cmp != 0:
            return False
        if op == "!=" and cmp == 0:
            return False
        if op == ">=" and cmp < 0:
            return False
        if op == "<=" and cmp > 0:
            return False
        if op == ">" and cmp <= 0:
            return False
        if op == "<" and cmp >= 0:
            return False
        if op == "~=":
            if _compare(ver, sver) < 0:
                return False
            upper = _upper_bound_for_compatible(sver)
            if _compare(ver, upper) >= 0:
                return False
    return True


def max_satisfying(versions, spec):
    parsed_versions = []
    for v in versions:
        parsed_versions.append((v, _parse_version(v)))

    clauses = _parse_spec(spec)

    best_original = None
    best_tuple = None

    for original, ver in parsed_versions:
        ok = True
        for op, sver in clauses:
            cmp = _compare(ver, sver)
            if op == "==" and cmp != 0:
                ok = False
                break
            if op == "!=" and cmp == 0:
                ok = False
                break
            if op == ">=" and cmp < 0:
                ok = False
                break
            if op == "<=" and cmp > 0:
                ok = False
                break
            if op == ">" and cmp <= 0:
                ok = False
                break
            if op == "<" and cmp >= 0:
                ok = False
                break
            if op == "~=":
                if _compare(ver, sver) < 0:
                    ok = False
                    break
                upper = _upper_bound_for_compatible(sver)
                if _compare(ver, upper) >= 0:
                    ok = False
                    break
        if not ok:
            continue
        if best_tuple is None or _compare(ver, best_tuple) > 0:
            best_tuple = ver
            best_original = original
        # if equal, keep the first one (do nothing)

    return best_original
