def parse_port(s):
    s = s.strip()
    if not s:
        raise ValueError("invalid port: " + s)
    if not s.isascii() or not s.isdigit():
        raise ValueError("invalid port: " + s)
    if len(s) > 1 and s[0] == "0":
        raise ValueError("invalid port: " + s)
    n = int(s)
    if not 1 <= n <= 65535:
        raise ValueError("port out of range: " + s)
    return n
