import decimal
import re
from collections import deque


class FifoBook:
    _PRICE_RE = re.compile(r'^[0-9]+(?:\.[0-9]{1,4})?$')

    def __init__(self):
        self._lots = deque()
        self._realized = decimal.Decimal('0.00')

    @staticmethod
    def _validate_qty(qty):
        if type(qty) is not int:
            raise TypeError('qty must be int')
        if qty <= 0:
            raise ValueError('qty must be positive')

    @staticmethod
    def _parse_price(price):
        if type(price) is not str:
            raise TypeError('price must be str')
        if not FifoBook._PRICE_RE.match(price):
            raise ValueError('invalid price format')
        return decimal.Decimal(price)

    def buy(self, qty, price):
        self._validate_qty(qty)
        parsed_price = self._parse_price(price)
        self._lots.append([qty, price, parsed_price])

    def sell(self, qty, price):
        self._validate_qty(qty)
        sell_price = self._parse_price(price)

        if qty > self.holdings():
            raise ValueError('insufficient holdings')

        remaining = qty
        raw_pnl = decimal.Decimal('0')
        while remaining > 0:
            lot_qty, lot_price_str, lot_price = self._lots[0]
            take = lot_qty if remaining >= lot_qty else remaining
            raw_pnl += (sell_price - lot_price) * take
            if take == lot_qty:
                self._lots.popleft()
            else:
                self._lots[0][0] = lot_qty - take
            remaining -= take

        quantized = raw_pnl.quantize(decimal.Decimal('0.01'), rounding=decimal.ROUND_HALF_EVEN)
        self._realized += quantized
        return quantized

    def realized(self):
        return self._realized

    def holdings(self):
        total = 0
        for lot in self._lots:
            total += lot[0]
        return total

    def lots(self):
        return [(lot[0], lot[1]) for lot in self._lots]

    def cost_basis(self):
        total = decimal.Decimal('0')
        for lot in self._lots:
            total += lot[2] * lot[0]
        return total.quantize(decimal.Decimal('0.01'), rounding=decimal.ROUND_HALF_EVEN)
