import copy


def _decode_pointer(pointer):
    if pointer == "":
        return []
    if not pointer.startswith("/"):
        raise ValueError("Non-empty pointer must start with '/'")
    tokens = pointer[1:].split("/")
    decoded = []
    for token in tokens:
        decoded_token = []
        i = 0
        while i < len(token):
            ch = token[i]
            if ch == "~":
                if i + 1 >= len(token):
                    raise ValueError("Unescaped '~' at end of token")
                nxt = token[i + 1]
                if nxt == "0":
                    decoded_token.append("~")
                    i += 2
                elif nxt == "1":
                    decoded_token.append("/")
                    i += 2
                else:
                    raise ValueError("Invalid escape sequence in pointer token")
            else:
                decoded_token.append(ch)
                i += 1
        decoded.append("".join(decoded_token))
    return decoded


def resolve(doc, pointer):
    tokens = _decode_pointer(pointer)
    current = doc
    for token in tokens:
        if isinstance(current, dict):
            if token not in current:
                raise KeyError(token)
            current = current[token]
        elif isinstance(current, list):
            if token == "-":
                raise KeyError(token)
            if token == "0":
                idx = 0
            else:
                if not token.isdigit() or token[0] == "0":
                    raise KeyError(token)
                idx = int(token)
            if idx < 0 or idx >= len(current):
                raise KeyError(token)
            current = current[idx]
        else:
            raise KeyError(token)
    return current


def set_value(doc, pointer, value):
    tokens = _decode_pointer(pointer)
    if not tokens:
        return copy.deepcopy(value)
    new_doc = copy.deepcopy(doc)
    current = new_doc
    for token in tokens[:-1]:
        if isinstance(current, dict):
            if token not in current:
                raise KeyError(token)
            current = current[token]
        elif isinstance(current, list):
            if token == "-":
                raise KeyError(token)
            if token == "0":
                idx = 0
            else:
                if not token.isdigit() or token[0] == "0":
                    raise KeyError(token)
                idx = int(token)
            if idx < 0 or idx >= len(current):
                raise KeyError(token)
            current = current[idx]
        else:
            raise KeyError(token)
    last = tokens[-1]
    if isinstance(current, dict):
        current[last] = copy.deepcopy(value)
    elif isinstance(current, list):
        if last == "-":
            current.append(copy.deepcopy(value))
        elif last == "0":
            idx = 0
        else:
            if not last.isdigit() or last[0] == "0":
                raise KeyError(last)
            idx = int(last)
        if last != "-":
            if idx < 0 or idx > len(current):
                raise KeyError(last)
            if idx == len(current):
                current.append(copy.deepcopy(value))
            else:
                current[idx] = copy.deepcopy(value)
    else:
        raise KeyError(last)
    return new_doc


def escape_token(token):
    return token.replace("~", "~0").replace("/", "~1")
