def wrap_text(text, width):
    if not isinstance(width, int) or width < 2:
        raise ValueError("width must be an int >= 2")

    words = text.split()
    if not words:
        return []

    lines = []
    current = ""

    def flush():
        nonlocal current
        if current:
            lines.append(current)
            current = ""

    for word in words:
        if len(word) <= width:
            # Normal greedy placement
            if current == "":
                current = word
            elif len(current) + 1 + len(word) <= width:
                current += " " + word
            else:
                lines.append(current)
                current = word
        else:
            # Long word: must start a new line
            flush()

            chunk_size = width - 1
            remaining = word
            while len(remaining) > width:
                chunk = remaining[:chunk_size]
                lines.append(chunk + "-")
                remaining = remaining[chunk_size:]
            current = remaining

    flush()
    return lines
